      "book": "mutation CreateReservation($classInstanceId: ID!) { createReservation(classInstanceId: $classInstanceId) { reservation { id status waitlistPosition } errorCode } }",
      "cancel": "mutation CancelReservation($reservationId: ID!) { cancelReservation(reservationId: $reservationId) { reservationId success } }"
